// 订单
export type orderservicev1_Order = {
  businessRefId?: string;
  createdAt?: wellKnownTimestamp;
  createdBy?: number;
  currency?: string;
  deletedAt?: wellKnownTimestamp;
  deletedBy?: number;
  discountAmount?: number;
  id?: number;
  idempotencyKey?: string;
  originalAmount?: number;
  recipientName?: string;
  recipientPhone?: string;
  shippingAddress?: string;
  status?: orderservicev1_Order_Status;
  tenantId?: number;
  totalAmount?: number;
  updatedAt?: wellKnownTimestamp;
  updatedBy?: number;
  userId?: number;
};

// 订单状态
// 
// 订单状态流转规则：
// 初始：PENDING_PAYMENT
// 成功路径：PENDING_PAYMENT → PAID → FULFILLED → CLOSED
// 取消路径：PENDING_PAYMENT → CANCELLED（超时未支付自动取消并释放库存）
// 终态不可回退：CANCELLED / CLOSED
export type orderservicev1_Order_Status =
  | 'CANCELLED'
  | 'CLOSED'
  | 'FULFILLED'
  | 'PAID'
  | 'PENDING_PAYMENT'
  | 'STATUS_UNSPECIFIED';
export type orderservicev1_CountOrderResponse = {
  count: number | undefined;
};

export type orderservicev1_GetOrderRequest = {
  id?: number;
  idempotencyKey?: string;
  // 按 idempotency_key 查询时必须携带的租户ID（唯一索引为 tenant_id + idempotency_key）。
  tenantId?: number;
  viewMask?: wellKnownFieldMask;
};

export type orderservicev1_UpdateOrderRequest = {
  allowMissing?: boolean;
  data: orderservicev1_Order | undefined;
  // 状态前置条件（乐观状态机）：仅当订单当前 status ∈ expected_status 时更新才生效，
  // 否则 affected_rows=0 返回 Conflict。留空表示不校验。
  // 用于并发场景下防止终态被覆盖。
  expectedStatus: orderservicev1_Order_Status[] | undefined;
  id: number | undefined;
  updateMask: undefined | wellKnownFieldMask;
};

export type orderservicev1_DeleteOrderRequest = {
  id?: number;
};

